import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener ensemble, capped at five active factors.
FACTORS = {
    "miner_3_clv_1d": (0.27, "clv"),
    "peer_median_leadlag_5d": (0.25, "peer"),
    "miner_2_risk_adjusted_momentum_20d": (0.23, "mom"),
    "miner_2_relative_reversal_3d_vol": (0.15, "rev3"),
    "miner_3_smoothed_intraday_reversal_1d": (0.10, "irev"),
}
REBALANCE_BLOCK = 10
MIN_W, MAX_W = 0.025, 0.15
last_date = None
prior_score = None


def cs_rank(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / n if n > 1 else 0.5
    return out


def bounded_weights(raw):
    # Iterative capped-simplex projection; always returns all 15 names.
    free = set(UNIVERSE)
    ans = {}
    for _ in range(20):
        if not free:
            break
        remaining = 1.0 - sum(ans.values())
        denom = sum(max(raw[s], 1e-9) for s in free)
        trial = {s: remaining * max(raw[s], 1e-9) / denom for s in free}
        lo = [s for s in free if trial[s] < MIN_W]
        hi = [s for s in free if trial[s] > MAX_W]
        if not lo and not hi:
            ans.update(trial)
            break
        chosen, bound = (lo, MIN_W) if lo else (hi, MAX_W)
        for s in chosen:
            ans[s] = bound
            free.remove(s)
    for s in free:
        ans[s] = max(ans.get(s, 0), 0)
    total = sum(ans.values())
    return {s: ans.get(s, 0.0) / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_date, prior_score
    obs = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=110)
        if df is None or len(df) < 35:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df.close, dtype=float)
        o = np.asarray(df.open, dtype=float)
        h = np.asarray(df.high, dtype=float)
        l = np.asarray(df.low, dtype=float)
        v = np.asarray(df.volume, dtype=float) if "volume" in df else np.ones(len(df))
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1
        obs[s] = (c, o, h, l, v, r, str(df.iloc[-1].date))
    if len(obs) < 12:
        return
    d = max(x[-1] for x in obs.values())
    # Ten trading days is approximately two calendar weeks. This gate also
    # avoids repeated proposals on the daily mark-to-market calls.
    if last_date is not None:
        try:
            if (np.datetime64(d) - np.datetime64(last_date)) / np.timedelta64(1, "D") < 13:
                return
        except Exception:
            return

    vals = {k: {} for k in FACTORS}
    invvol, returns = {}, {}
    for s, (c, o, h, l, v, r, _) in obs.items():
        vol = max(float(np.std(r[-20:])), 0.008)
        invvol[s] = 1.0 / vol
        returns[s] = float(c[-1] / max(c[-6], 1e-12) - 1)
        clv = (2*c - h - l) / np.maximum(h-l, 1e-12)
        intr = -(c / np.maximum(o, 1e-12) - 1) / np.maximum(np.std(r[-20:]), .008)
        vals["clv"][s] = float(clv[-1])
        vals["peer"][s] = returns[s]
        vals["mom"][s] = float((c[-1] / max(c[-21], 1e-12) - 1) / vol)
        vals["rev3"][s] = float(-(c[-1] / max(c[-4], 1e-12) - 1) / vol)
        vals["irev"][s] = float(np.mean(intr[-3:]))
    med = float(np.median(list(vals["peer"].values())))
    vals["peer"] = {s: x-med for s, x in vals["peer"].items()}
    ranks = {k: cs_rank(x) for k, x in vals.items()}
    score = {s: sum(w*ranks[key].get(s, .5) for _, (w, key) in FACTORS.items()) for s in UNIVERSE}
    if prior_score is not None:
        score = {s: .75*prior_score.get(s, score[s]) + .25*score[s] for s in UNIVERSE}
    prior_score = dict(score)

    breadth = np.mean([x[0][-1] > x[0][-21] for x in obs.values()])
    market_vol = float(np.mean([np.std(x[5][-20:]) for x in obs.values()]))
    # High-risk bearish/sideways posture: full investment, defensive tilt.
    if breadth < .55 or market_vol > .025:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .16
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .06

    mean_iv = np.mean(list(invvol.values()))
    raw = {s: max(score[s], .05) * (.70 + .30*invvol[s]/max(mean_iv, 1e-12)) for s in UNIVERSE}
    weights = bounded_weights(raw)
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-12)
    forecast = {s: float(.01*(score[s]-mu)/sd) for s in UNIVERSE}
    ids = list(FACTORS)
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_date = d

if __name__ == "__main__":
    pass

